window.RP_SESSION={"id":"S-f49b97e9a568","messages":[{"id":"RP-0250144","time":"2026-08-26T02:22:00+09:00","room":"RP","name":"마리아 아나이스 에스테르","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"늦은 밤, 한참 내기에 푹 빠진 사람들 틈에 끼었습니다.\n\n' 그거 들었어? 저번에 싹 쓸어간 걔, 요즘 안 나오는 거. '\n\n' 딱 보니 먹을 거 다 먹고 짼 거잖아 등신아. '\n\n묘하게 기분 나쁜 말.\n\n\"갑자기 사라졌다고요?\"\n\n' 그래. 분명 며칠전만 해도 나와있었는데... '\n\n거하게 취한 남성은 말을 이었고, 한 귀로 흘렸습니다.","characters":["P-c9505ea97ebc"]},{"id":"RP-0250145","time":"2026-08-26T02:23:00+09:00","room":"RP","name":"마리아 아나이스 에스테르","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"... 음...\"\n\n' 그 자식이 이 판에서 유명한데... '\n\n\"에.....\"","characters":["P-c9505ea97ebc"]},{"id":"RP-0250146","time":"2026-08-26T02:25:00+09:00","room":"RP","name":"마리아 아나이스 에스테르","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"머리가 띵해지는 기분...\n\n불쾌하고도 서늘한 바람,\n\n\"ㅇ알겠어요... 고마워요\"\n\n급하게 사람들을 헤치고 나왔습니다.","characters":["P-c9505ea97ebc"]},{"id":"RP-0250147","time":"2026-08-26T02:26:00+09:00","room":"RP","name":"마리아 아나이스 에스테르","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"어우... 몰라몰라...\"\n\n\"숨 막혀 죽는줄 알았네...\"","characters":["P-c9505ea97ebc"]},{"id":"RP-0250148","time":"2026-08-26T02:28:00+09:00","room":"RP","name":"마리아 아나이스 에스테르","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"휴...\"\n\n조금 놀란 가슴 쓸어내리며 골목 벽에 기대었습니다","characters":["P-c9505ea97ebc"]},{"id":"RP-0250149","time":"2026-08-26T02:32:00+09:00","room":"RP","name":"마리아 아나이스 에스테르","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"으으... 너무 싫어. 무슨 구경도 하지 말라는 벌이야...?\"\n\n투덜투덜 별것 아닌 불만을 쏟아내곤 고개를 들었습니다","characters":["P-c9505ea97ebc"]},{"id":"RP-0250150","time":"2026-08-26T02:32:00+09:00","room":"RP","name":"마리아 아나이스 에스테르","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"!의지","characters":["P-c9505ea97ebc"]},{"id":"RP-0250151","time":"2026-08-26T02:32:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'Maria Anaïs Ésther'의 의지 판정 :\n[2] + [4] = [6]\n결과 : 쓰라린 실패, 운명을 빗겨갈 순 없습니다.","characters":[]},{"id":"RP-0250152","time":"2026-08-26T02:33:00+09:00","room":"RP","name":"마리아 아나이스 에스테르","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"...?\"\n\n베일을 살짝 걷어 눈을 찌푸려 골목 끝을 살핍니다","characters":["P-c9505ea97ebc"]},{"id":"RP-0250153","time":"2026-08-26T02:34:00+09:00","room":"RP","name":"마리아 아나이스 에스테르","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"익숙한 뒤통수... \n\n\"저거 그때 나한테 한방 먹인 걔 아냐...?\"","characters":["P-c9505ea97ebc"]},{"id":"RP-0250154","time":"2026-08-26T02:35:00+09:00","room":"RP","name":"마리아 아나이스 에스테르","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"야!!! 너 다음에 온다며!! 내가 얼마나 기다렸는지 알아?\"\n\n길의 끝, 그것이 걸어가는 길을 향해 다가갔습니다\n\n\"어쩜 약속을 잡아놓고 지키지도 않아...! 내기도 그런게 얼마나 중요한데!\"","characters":["P-c9505ea97ebc"]},{"id":"RP-0250155","time":"2026-08-26T02:36:00+09:00","room":"RP","name":"마리아 아나이스 에스테르","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"걷던 걸음이 멈추고 그것의 어깨를 잡았습니다","characters":["P-c9505ea97ebc"]},{"id":"RP-0250156","time":"2026-08-26T02:36:00+09:00","room":"RP","name":"마리아 아나이스 에스테르","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"!의지","characters":["P-c9505ea97ebc"]},{"id":"RP-0250157","time":"2026-08-26T02:36:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'Maria Anaïs Ésther'의 의지 판정 :\n[8] + [4] = [12]\n결과 : 완벽한 성공, 운명은 당신의 편입니다.","characters":[]},{"id":"RP-0250158","time":"2026-08-26T02:51:00+09:00","room":"RP","name":"마리아 아나이스 에스테르","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"사진","characters":["P-c9505ea97ebc"]},{"id":"RP-0250159","time":"2026-08-26T02:51:00+09:00","room":"RP","name":"마리아 아나이스 에스테르","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"약속은 지켜ㅇ........\n\n\n아?\n\n여기... 어디...?\"","characters":["P-c9505ea97ebc"]},{"id":"RP-0250160","time":"2026-08-26T02:51:00+09:00","room":"RP","name":"마리아 아나이스 에스테르","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"아?????\"","characters":["P-c9505ea97ebc"]},{"id":"RP-0250161","time":"2026-08-26T02:51:00+09:00","room":"RP","name":"마리아 아나이스 에스테르","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-c9505ea97ebc"]},{"id":"RP-0250162","time":"2026-08-26T02:51:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"... 계속.","characters":[]}]};
